import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root group
  const group = new THREE.Group();
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Parse colors
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Create plane geometry (2:1.25 aspect from atlas region 512x320)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load brushed metal texture
  let texturePromise = Promise.resolve(null);
  if (config.imageUrl) {
    texturePromise = ctx.textureLoader.loadTexture(config.imageUrl).catch(() => null);
  }

  texturePromise.then((metalTexture) => {
    // Build material with gradient + texture
    const uvNode = uv();

    // Vertical gradient: surface at bottom to ink at top
    const gradientNode = mix(
      color(colors.surface),
      color(colors.ink),
      uvNode.y
    );

    // Texture blend (if loaded, otherwise just gradient)
    let finalColorNode = gradientNode;
    if (metalTexture) {
      metalTexture.colorSpace = THREE.SRGBColorSpace;
      const sampledMetal = new THREE.TextureNode(metalTexture);
      finalColorNode = mix(gradientNode, sampledMetal, 0.3);
    }

    const material = new MeshBasicNodeMaterial();
    material.colorNode = finalColorNode;
    material.transparent = true;

    const mesh = new THREE.Mesh(geometry, material);
    group.add(mesh);
  });

  // Render headline text via fontAtlas
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find(item => item.role === 'headline') || 
                       { text: 'Collection 2', fontSize: 39 };

  const headlineText = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize ?? 39,
    color: colors.paper,
    align: 'center'
  });

  // Position text centered on plane, slightly above middle
  headlineText.position.set(0, 0.15, 0.01);
  group.add(headlineText);

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    texturePromise.then((tex) => {
      if (tex) tex.dispose();
    });
    group.children.forEach((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
